// The pattern for each invocation is:
//
//     define_hashmap!(HashMap<K><V>, <key Rust ty>, <value Rust ty>,
//                     <miss-sentinel expr>);
//
// 99 invocations follow, grouped by key type.

// ---- key: bool ----
define_hashmap!(HashMapBoolBool, bool, bool, false);
define_hashmap!(HashMapBoolI8, bool, i8, i8::MIN);
define_hashmap!(HashMapBoolI16, bool, i16, i16::MIN);
define_hashmap!(HashMapBoolI32, bool, i32, i32::MIN);
