define_hashmap!(HashMapU64I64, u64, i64, i64::MIN);
define_hashmap!(HashMapU64U8, u64, u8, u8::MAX);
define_hashmap!(HashMapU64U16, u64, u16, u16::MAX);
define_hashmap!(HashMapU64U32, u64, u32, u32::MAX);
define_hashmap!(HashMapU64U64, u64, u64, u64::MAX);
